<script lang="ts">
 import CzechProgress from '$lib/components/CzechProgress.svelte';
 import {onDestroy,onMount,tick} from 'svelte';
 import {user,userReady} from '$lib/stores/user';
 import {SKILLS,LESSONS,emptyState,rankedLessons,studyPrompt,validatePatch,elapsed,gapsTsv,topicScore,type Skill,type Focus,type Patch} from '$lib/czech/study';
 import {subscribeCzech,importPractice,changeTimer,exportCzech} from '$lib/czech/repository';
 let state=emptyState(),loading=true,busy=false,error='',notice='',loadedUid='',track='All',focus:Focus='mixed',chosen='',patchText='',preview:Patch|null=null,promptText='',now=Date.now(),tab='practice';
 let unsubscribe:(()=>void)|undefined;
 const labels:Record<Focus,string>={mixed:'Mixed practice',listening:'Listening',speaking:'Speaking',reading:'Reading',writing:'Writing'};
 $: uid=$user?.uid as string|undefined;
 $: if($userReady&&uid&&uid!==loadedUid){unsubscribe?.();loadedUid=uid;loading=true;state=emptyState();patchText='';preview=null;promptText='';unsubscribe=subscribeCzech(uid,s=>{state=s;loading=false;},e=>{error=e.message;loading=false;});}
 $: if($userReady&&!uid){unsubscribe?.();unsubscribe=undefined;loadedUid='';state=emptyState();loading=false;}
 $: lessons=rankedLessons(state,track,focus);
 $: selected=LESSONS.find(l=>l.id===chosen)??lessons[0];
 $: gaps=state.gaps.filter(g=>!g.resolvedAt&&(track==='All'||LESSONS.find(l=>l.id===g.lessonId)?.track===track));
 $: timerSeconds=state.timer?elapsed(state.timer,now):0;
 $: assessed=Object.values(state.assessments).reduce((n,a)=>n+Object.keys(a).length,0);
 onMount(()=>{const interval=setInterval(()=>now=Date.now(),1000);return()=>clearInterval(interval);});
 onDestroy(()=>unsubscribe?.());
 async function chooseTopic(id:string){chosen=id;track='All';tab='practice';await tick();document.getElementById('czech-practice')?.scrollIntoView({block:'start'});}
 const time=(seconds:number)=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
 async function action(task:()=>Promise<unknown>,success:string){if(busy||!uid)return;busy=true;error='';notice='';try{await task();notice=success;}catch(e){error=e instanceof Error?e.message:'Could not save. Please retry.';}finally{busy=false;}}
 async function copyPrompt(){
  if(!selected||!uid||busy)return;
  promptText=studyPrompt(state,selected.id,focus,`czech-${crypto.randomUUID()}`);
  try{await navigator.clipboard.writeText(promptText);}catch{error='Clipboard unavailable. Copy the prompt from the field below.';return;}
  await action(()=>changeTimer(uid!,'start',selected.id),'Prompt copied · practice timer running.');
 }
 function inspect(){preview=null;error='';try{preview=validatePatch(JSON.parse(patchText.trim().replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,'')));}catch(e){error=e instanceof Error?e.message:'Invalid JSON.';}}
 async function apply(){if(!preview)return;await action(async()=>{const saved=await importPractice(uid!,preview!);if(!saved)throw new Error('This patch was already imported. Nothing was counted twice.');preview=null;patchText='';},'Practice saved. Skills and gaps updated.');}
 async function upload(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;if(file.size>1000000){error='Choose a JSON patch smaller than 1 MB.';return;}patchText=await file.text();inspect();}
 function download(name:string,text:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
</script>
<svelte:head><title>Czech practice · Trackr</title><meta name="description" content="Everyday and clinical Czech practice, with separate listening, speaking, reading and writing progress."/></svelte:head>
<main class="czech">
 <header><div><h1>A little Czech.<br/>Every day.</h1><p>Everyday conversations. Clearer patient communication.<br/>Start where you are. Keep growing, one conversation at a time.</p></div><div class="record"><strong>{Math.floor(state.studySeconds/60)} min</strong><span>practice saved</span><span>{state.practiceCount} sessions · {assessed} skill assessments</span></div></header>
 {#if loading}<p role="status">Loading your Czech practice…</p>{:else if !uid}<p>Sign in to save practice across your phone and computer.</p>{:else}
 <div class="toolbar"><label class="mobile-area">Area<select bind:value={track} on:change={()=>chosen=''}>{#each ['All','Everyday','Clinic'] as area}<option value={area}>{area}</option>{/each}</select></label><div class="segments" aria-label="Practice area">{#each ['All','Everyday','Clinic'] as name}<button class:active={track===name} aria-pressed={track===name} on:click={()=>{track=name;chosen='';}}>{name}</button>{/each}</div><nav aria-label="Czech views"><button class:active={tab==='practice'} on:click={()=>tab='practice'}>Practice</button><button class:active={tab==='gaps'} on:click={()=>tab='gaps'}>Gaps <span>{gaps.length}</span></button><button class:active={tab==='progress'} on:click={()=>tab='progress'}>Progress</button></nav></div>
 {#if state.timer}<section class="timer" aria-label="Practice timer"><div><span>{state.timer.status==='paused'?'Paused':'Practising'} · {LESSONS.find(l=>l.id===state.timer?.lessonId)?.title}</span><strong>{time(timerSeconds)}</strong></div><div class="buttons"><button disabled={busy} on:click={()=>action(()=>changeTimer(uid!,state.timer?.status==='running'?'pause':'resume',state.timer!.lessonId),'Timer updated.')}>{state.timer.status==='running'?'Pause':'Resume'}</button><button disabled={busy} on:click={()=>action(()=>changeTimer(uid!,'finish',state.timer!.lessonId),'Active practice time saved.')}>Finish & save time</button><button disabled={busy} on:click={()=>action(()=>changeTimer(uid!,'cancel',state.timer!.lessonId),'Timer discarded. No study time saved.')}>Cancel</button></div></section>{/if}
 {#if error}<div class="error" role="alert">{error}<button on:click={()=>error=''} aria-label="Dismiss error">Dismiss</button></div>{/if}
 {#if notice}<p class="notice" role="status">{notice}</p>{/if}
 {#if tab==='practice'}
 <div class="mobile-selectors"><label>Lesson<select value={selected.id} on:change={e=>chosen=e.currentTarget.value}>{#each lessons as l}<option value={l.id}>{l.title}</option>{/each}</select></label><label>Focus<select bind:value={focus}><option value="mixed">Mixed practice</option>{#each SKILLS as skill}<option value={skill}>{labels[skill]}</option>{/each}</select></label></div><div class="workspace" id="czech-practice"><section class="lesson-list"><h2>What shall we practise?</h2><label class="focus-label">Focus<select bind:value={focus}><option value="mixed">Mixed practice</option>{#each SKILLS as skill}<option value={skill}>{labels[skill]}</option>{/each}</select></label><p class="muted">Unassessed first, then weak or older skills.</p>{#each lessons as l}<button class:selected={selected?.id===l.id} on:click={()=>chosen=l.id}><span>{l.title}<small>{l.track}</small></span><span class="score">{(focus==='mixed'?topicScore(state,l.id)?.toFixed(1):state.assessments[l.id]?.[focus]?.score)??'—'}<small>/4</small></span></button>{/each}</section>
 <section class="practice-panel"><div class="lesson-title"><span>{selected.track} · {labels[focus]}</span><h2>{selected.title}</h2><p>{selected.goal}</p></div><div class="session-start"><h3>10–15 minutes. One real exchange.</h3><p>{focus==='mixed'?'A short dialogue, a little reading and a written reply. The tutor adapts the mix and difficulty to your answers; listening requires real audio.':focus==='listening'?'Listen before seeing the text. If your study chat has no audio, listening stays unassessed.':focus==='speaking'?'Use voice mode for a short role-play. Answer first, receive a brief correction, then try a new situation.':'Work through a short Czech text or message, then get feedback on what you produced independently.'}</p><button class="primary" disabled={busy} on:click={copyPrompt}>Copy practice prompt & start timer</button> <button disabled={busy} on:click={()=>action(()=>changeTimer(uid!,'start',selected.id),'Practice timer started.')}>Start timer only</button></div><div class="skill-grid">{#each SKILLS as skill}<button class:focused={focus===skill} on:click={()=>focus=skill}><span>{labels[skill]}</span><strong>{state.assessments[selected.id]?.[skill]?.score??'—'}<small>/4</small></strong><small>{state.assessments[selected.id]?.[skill]?'Observed practice':'Not assessed'}</small></button>{/each}</div>
 {#if focus!=='mixed' && state.assessments[selected.id]?.[focus]}<details><summary>Latest {labels[focus].toLowerCase()} feedback</summary><p>{state.assessments[selected.id]?.[focus]?.evidence}</p></details>{/if}

 {#if promptText}<details><summary>Show prompt / copy manually</summary><textarea readonly value={promptText} aria-label="Czech study prompt"></textarea></details>{/if}
 <section class="patch"><h3>Bring your practice back</h3><p>Your study chat finishes with one Czech patch. Paste it here to save skill evidence and useful mistakes.</p><textarea bind:value={patchText} on:input={()=>preview=null} placeholder='Paste your Czech JSON patch…' aria-label="Czech practice patch"></textarea><div class="buttons"><button disabled={busy||!patchText.trim()} on:click={inspect}>Check patch</button><label class="upload">Choose JSON file<input type="file" accept=".json,application/json" on:change={upload}/></label></div>{#if preview}<div class="preview"><p>{preview.assessments.length} skill updates · {preview.addGaps.length} new gaps · {preview.resolveGapIds.length} resolved · {preview.vocabulary?.length??0} vocabulary entries</p><button class="primary" disabled={busy} on:click={apply}>Apply practice patch</button></div>{/if}</section>
 <p class="muted">0: not yet · 1: substantial help · 2: partial · 3: independent · 4: robust in this task. These are task-specific practice ratings. Difficulty keeps growing; a topic never becomes permanently finished.</p></section></div>
 {:else if tab==='gaps'}<section class="gap-view"><div class="gap-head"><h2>Mistakes worth revisiting</h2><button disabled={!gaps.length} on:click={()=>download('czech-gaps.tsv',gapsTsv({...state,gaps}),'text/tab-separated-values')}>Export for Anki</button></div><p class="muted">Front, back and tags · tab-separated. Import as basic cards. Resolve a gap after a later independent answer.</p>{#each gaps as gap}<details><summary><span>{gap.prompt}<small>{labels[gap.skill]} · {LESSONS.find(l=>l.id===gap.lessonId)?.title}</small></span></summary><p lang="cs">{gap.answer}</p></details>{:else}<p>No open gaps yet. Your first practice patch will put specific recall tasks here.</p>{/each}</section>{/if}
 <CzechProgress {uid} {state} onchoose={chooseTopic} />
 <footer><span>Your Czech progress is separate from your exam archives.</span><button disabled={busy} on:click={()=>action(async()=>download('trackr-czech-backup.json',JSON.stringify(await exportCzech(uid!,state),null,2)),'Backup downloaded.')}>Export full backup</button></footer>
 {/if}
</main>
<style>
 .czech{--fg:#edf0f6;--muted:#a7afc1;--line:#303746;--panel:#151b26;--accent:#b4adff;color:var(--fg);max-width:1360px;margin:auto;padding:32px 20px 100px;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;caret-color:var(--accent)}.czech ::selection{background:#51486e;color:#fff}.czech :global(:focus-visible){outline:2px solid #c3bcff;outline-offset:4px}h1{font-size:clamp(2.6rem,5vw,3.5rem);letter-spacing:-.035em;line-height:1.04;margin:0 0 18px;text-wrap:balance}h2{font-size:1.35rem;letter-spacing:-.02em;margin:0 0 12px}h3{font-size:1rem;margin:0 0 8px}p{line-height:1.6;max-width:70ch}header{display:flex;align-items:flex-end;justify-content:space-between;gap:32px;margin:12px 0 24px}header p{color:var(--muted);margin:0}.record{display:grid;gap:6px;color:var(--muted);padding-bottom:6px}.record strong{font-size:1.75rem;color:var(--fg);font-variant-numeric:tabular-nums}.record span{font-size:.8rem}button,select,textarea{font:inherit;color:inherit}button,.upload{border:1px solid var(--line);border-radius:9px;background:#1c2330;padding:10px 14px;cursor:pointer;min-height:44px;font-size:.85rem;touch-action:manipulation}button{transition:background-color 140ms ease-out,transform 120ms ease-out}button:active{transform:scale(.98)}button:disabled{opacity:.5;cursor:not-allowed}.toolbar{display:flex;justify-content:space-between;gap:16px;padding:16px 0;border-block:1px solid var(--line);margin-bottom:24px}.segments,nav,.buttons{display:flex;gap:6px;flex-wrap:wrap}.segments{padding:3px;background:#111721;border-radius:11px}.segments button,nav button{background:none;border-color:transparent}.segments button.active,nav button.active{background:#343247;color:#e5e0ff}nav span{font-variant-numeric:tabular-nums}.workspace{display:grid;grid-template-columns:300px minmax(0,1fr);gap:40px}.lesson-list{border-right:1px solid var(--line);padding-right:24px}.focus-label{display:flex;align-items:center;justify-content:space-between;color:var(--muted);font-size:.85rem}.focus-label select{background:#1c2330;border:1px solid var(--line);border-radius:8px;padding:10px;min-height:44px}.lesson-list>button{display:flex;align-items:center;justify-content:space-between;width:100%;gap:14px;text-align:left;background:none;border-color:transparent;border-radius:8px;margin:3px 0;padding:12px}.lesson-list>button.selected{background:#262538;border-color:#4b4565}.lesson-list small{display:block;font-size:.72rem;color:var(--muted);margin-top:5px}.score{min-width:24px;text-align:right}.score small{display:inline;font-size:.65rem;margin-left:3px}.muted{color:var(--muted);font-size:.77rem}.lesson-title>span{color:var(--accent);font-size:.85rem}.lesson-title h2{margin-top:12px;font-size:2rem}.lesson-title p,.session-start p,.patch p{color:var(--muted);font-size:.9rem}.skill-grid{display:grid;grid-template-columns:repeat(4,1fr);border-block:1px solid var(--line);padding:18px 0;margin:28px 0;gap:10px}.skill-grid button{display:grid;gap:8px;border:0;background:none;text-align:left;padding:10px}.skill-grid button.focused{background:#242235}.skill-grid span{font-size:.78rem;color:var(--muted)}.skill-grid strong{font-size:1.65rem;font-variant-numeric:tabular-nums}.skill-grid strong small{font-size:.8rem;color:var(--muted);margin-left:4px}.skill-grid>button>small{font-size:.65rem;color:var(--muted)}.session-start{padding:4px 0 28px}.primary{background:#b4adff;border-color:#b4adff;color:#161222;font-weight:700}.patch{padding-top:28px;border-top:1px solid var(--line);margin-top:16px}textarea{box-sizing:border-box;width:100%;min-height:150px;resize:vertical;border:1px solid var(--line);border-radius:9px;background:#101620;padding:14px;font-size:16px;line-height:1.5}textarea::placeholder{color:#9da6b7}.buttons{margin:12px 0}.upload{display:inline-flex;align-items:center}.upload input{width:1px;height:1px;opacity:0;position:absolute}.upload:focus-within{outline:2px solid var(--accent)}details{border-bottom:1px solid var(--line);padding:14px 0}summary{cursor:pointer;min-height:24px;font-size:.88rem}summary small{display:block;color:var(--muted);margin-top:5px}.preview{background:#242235;border-radius:9px;padding:16px;margin-top:12px}.timer{display:flex;justify-content:space-between;align-items:center;gap:16px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:14px 18px;margin-bottom:24px}.timer>div:first-child{display:grid;gap:5px}.timer span{font-size:.8rem;color:var(--muted)}.timer strong{font-size:1.8rem;font-variant-numeric:tabular-nums}.notice{color:#b3e2c9}.error{padding:12px;border:1px solid #b67680;border-radius:9px;color:#ffc4cc;display:flex;justify-content:space-between;gap:12px;margin-bottom:20px}.gap-head{display:flex;justify-content:space-between;gap:16px;align-items:center}.gap-view details p{padding:0 16px}.gap-view summary{line-height:1.5}footer{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-top:48px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted);font-size:.75rem}@media(hover:hover)and(pointer:fine){button:not(:disabled):hover{background:#343044}.primary:not(:disabled):hover{background:#cbc6ff}}.mobile-area,.mobile-selectors{display:none}select{max-width:100%;font-size:16px} @media(max-width:760px){.segments,.lesson-list{display:none}.mobile-area{display:flex;align-items:center;gap:8px;font-size:.8rem;color:var(--muted)}.mobile-area select,.mobile-selectors select{background:#1c2330;color:var(--fg);border:1px solid var(--line);border-radius:8px;min-height:44px;padding:8px;min-width:0}.mobile-selectors{display:grid;grid-template-columns:minmax(0,1fr) 125px;gap:12px;margin-bottom:24px}.mobile-selectors label{display:grid;gap:6px;font-size:.8rem;color:var(--muted)}.toolbar{flex-wrap:nowrap;gap:8px}.session-start{padding-bottom:8px}.czech{padding:22px 8px 100px}header{align-items:flex-start;gap:20px}header .record{max-width:135px;font-size:.75rem}.workspace{grid-template-columns:1fr;gap:24px}.lesson-list{border:0;padding:0;max-height:275px;overflow:auto;border-bottom:1px solid var(--line);padding-bottom:12px}.toolbar{flex-wrap:wrap;margin-bottom:16px}.timer,footer{align-items:flex-start;flex-direction:column}.skill-grid{gap:0}.skill-grid button{padding:8px 5px}.skill-grid>button>small{font-size:.6rem}.lesson-title h2{font-size:1.6rem}.gap-head{align-items:flex-start;flex-direction:column}}@media(max-width:420px){header{flex-direction:column}header .record{max-width:none;grid-template-columns:auto auto;align-items:baseline}.record span:last-child{grid-column:1/-1}.skill-grid{grid-template-columns:repeat(2,1fr);row-gap:14px}}@media(prefers-reduced-motion:reduce){button{transition:none}button:active{transform:none}}
</style>
